# ----------------------------------------------------------------------- CLI
def _report(store_path, settlement=False):
    store = w.Store(store_path)
    store.require()
    results = check_store(store)
    if not results:
        print(f"{PROFILE}: no provenance documents in {store_path}")
        return 0
